<?php
declare(strict_types=1);
namespace ReadyFinance;
final class AccountManagementService {
 public function __construct(private Core $c){}
 public function ready():bool{return (bool)$this->c->query("SELECT COUNT(*) FROM schema_migrations WHERE version='006_editing'")->fetchColumn();}
 public function upgrade():array {$c=$this->c;if(!(new ChartService($c))->ready())throw new Fault('Enable the chart of accounts first.');if(!$c->query('SELECT GET_LOCK("rpf_editing_upgrade",10)')->fetchColumn())throw new Fault('Upgrade is busy.',409);try{($migration=require dirname(__DIR__,3).'/database/006_editing.php')($c->db);return ['ok'=>true];}finally{$c->query('SELECT RELEASE_LOCK("rpf_editing_upgrade")');}}
 public function update(int $h,int $u,array $p,string $key,bool $money=false):array {
  if(!$this->ready())throw new Fault('Enable editing and review tools first.');if(!preg_match('/^[a-zA-Z0-9_.:-]{8,150}$/D',$key))throw new Fault('A valid command key is required.');$c=$this->c;
  return $c->atomic(function()use($c,$h,$u,$p,$key,$money){$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$command='account-update:'.$key;$hash=hash('sha256',json_encode([$money,$p],JSON_THROW_ON_ERROR));$old=$c->one('SELECT * FROM command_receipts WHERE household_id=? AND command_key=?',[$h,$command]);if($old){if($old['payload_hash']!==$hash)throw new Fault('Command key conflict.',409);return json_decode($old['result_json'],true);}
   $a=$c->scope($money?'accounts':'ledger_accounts',(string)($p['uuid']??''),$h,true);$ledger=$money?$c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$a['ledger_id']]):$a;
   if(($p['expected_name']??'')!==$a['name']||(string)($p['expected_active']??'')!==(string)$a['active'])throw new Fault('This account changed. Refresh and try again.',409);
   if(str_starts_with($ledger['system_key']??'','chart_'))throw new Fault('Keep the standard main headings. Manage their subaccounts instead.');
   $action=$p['action']??'';$name=$ledger['name'];$active=(int)$ledger['active'];$moneyAccount=$c->one('SELECT * FROM accounts WHERE household_id=? AND ledger_id=?',[$h,$ledger['id']]);$newType=$moneyAccount['type']??null;
   if($action==='rename'){if(isset($p['type'])&&$moneyAccount){$newType=$p['type'];if(!in_array($newType,['bank','cash','wallet','savings','credit_card'],true)||(($newType==='credit_card')!==($moneyAccount['type']==='credit_card')))throw new Fault('Keep this account in its original asset or credit-card class.');}$name=Core::text($p['name']??'',120);if($c->one('SELECT id FROM ledger_accounts WHERE household_id=? AND class=? AND parent_id<=>? AND name=? AND id<>?',[$h,$ledger['class'],$ledger['parent_id'],$name,$ledger['id']]))throw new Fault('This parent already has an account with that name.');}
   elseif($action==='archive'){
    if(!empty($ledger['system_key']))throw new Fault('This required system account stays available.');
    if($ledger['is_group']&&$c->one('SELECT id FROM ledger_accounts WHERE household_id=? AND parent_id=? AND active=1',[$h,$ledger['id']]))throw new Fault('Archive active child accounts first.');
    if(in_array($ledger['class'],['asset','liability'],true)&&bccomp($c->balance($h,(int)$ledger['id']),'0',6)!==0)throw new Fault('Transfer or settle this account balance before archiving.');
    $category=$c->one('SELECT id FROM categories WHERE household_id=? AND ledger_id=?',[$h,$ledger['id']]);if($category){$id=$category['id'];if($c->one("SELECT b.id FROM bills b WHERE b.household_id=? AND b.category_id=? AND b.amount>(SELECT COALESCE(SUM(ba.amount),0) FROM bill_allocations ba WHERE ba.household_id=b.household_id AND ba.bill_id=b.id)",[$h,$id])||$c->one('SELECT id FROM recurring_rules WHERE household_id=? AND category_id=? AND active=1',[$h,$id])||$c->one('SELECT id FROM budgets WHERE household_id=? AND category_id=? AND amount>0 AND month>=?',[$h,$id,substr($c->today($h),0,7)]))throw new Fault('Move this category’s entries and plans to another account before archiving.');}
    $account=$c->one('SELECT id FROM accounts WHERE household_id=? AND ledger_id=?',[$h,$ledger['id']]);if($account){if(bccomp((string)$c->query('SELECT COALESCE(SUM(fa.amount),0) FROM fund_allocations fa JOIN funds f ON f.id=fa.fund_id AND f.household_id=fa.household_id WHERE f.household_id=? AND f.account_id=?',[$h,$account['id']])->fetchColumn(),'0',6)!==0)throw new Fault('Release this account’s goal reservations first.');if($c->query("SELECT COUNT(*) FROM schema_migrations WHERE version='004_statement_import'")->fetchColumn()&&$c->one("SELECT r.id FROM import_rows r JOIN import_batches b ON b.id=r.batch_id AND b.household_id=r.household_id WHERE b.household_id=? AND b.account_id=? AND r.status='pending'",[$h,$account['id']]))throw new Fault('Finish or skip this account’s pending statement rows first.');}
    $active=0;
   }elseif($action==='restore'){if($ledger['parent_id']&&!$c->one('SELECT active FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$ledger['parent_id']])['active'])throw new Fault('Restore the parent group first.');$active=1;}else throw new Fault('Choose Edit name, Archive or Restore.');
   $c->query('UPDATE ledger_accounts SET name=?,active=? WHERE household_id=? AND id=?',[$name,$active,$h,$ledger['id']]);$c->query('UPDATE accounts SET name=?,active=? WHERE household_id=? AND ledger_id=?',[$name,$active,$h,$ledger['id']]);if($moneyAccount){$c->query('UPDATE accounts SET type=? WHERE household_id=? AND id=?',[$newType,$h,$moneyAccount['id']]);$c->query('UPDATE ledger_accounts SET account_kind=? WHERE household_id=? AND id=?',[$newType,$h,$ledger['id']]);}$c->query('UPDATE categories SET name=? WHERE household_id=? AND ledger_id=?',[$name,$h,$ledger['id']]);
   $result=['ok'=>true];$c->insert('command_receipts',['household_id'=>$h,'command_key'=>$command,'payload_hash'=>$hash,'result_json'=>json_encode($result),'created_at'=>Core::now()]);$c->audit($h,$u,'account.'.$action,$ledger['uuid'],['before_name'=>$ledger['name'],'name'=>$name,'active'=>$active,'before_type'=>$moneyAccount['type']??null,'type'=>$newType]);return $result;
  });
 }
}
